//! Wire DTO coverage for content generated by Creator's shared family planner.
use eldiron_network::*;
use eldiron_runtime::{ClientFrame, Project};
use eldiron_server::host::{Command, Host};
use shared::rulesets::equipment_family::{BONE_PIECES, BoneArmorFamily};
use std::time::Duration;
use theframework_core::Uuid;
use tokio::sync::mpsc;

async fn message(host: &mut Host, peer: Uuid, message: ClientMessage) {
    // Exercise the actual inbound codec, not just an in-memory engine action.
    let bytes = codec::encode_client(&message).unwrap();
    host.command(Command::Message {
        peer,
        message: codec::decode_client(&bytes).unwrap(),
    })
    .await
    .unwrap();
}
fn drain(rx: &mut mpsc::Receiver<Vec<u8>>) -> Vec<ServerMessage> {
    let mut messages = Vec::new();
    while let Ok(bytes) = rx.try_recv() {
        messages.push(codec::decode_server(&bytes).unwrap());
    }
    messages
}
async fn join(host: &mut Host, name: &str) -> (Uuid, mpsc::Receiver<Vec<u8>>, Uuid, ClientFrame) {
    let peer = Uuid::new_v4();
    let (output, mut rx) = mpsc::channel(64);
    host.command(Command::Open { peer, output }).await.unwrap();
    message(
        host,
        peer,
        ClientMessage::Hello {
            version: PROTOCOL_VERSION,
        },
    )
    .await;
    message(host, peer, ClientMessage::Guest { name: name.into() }).await;
    host.tick(Duration::from_millis(20)).await.unwrap();
    let messages = drain(&mut rx);
    let stream = messages
        .iter()
        .find_map(|m| {
            if let ServerMessage::ActionStream { stream, .. } = m {
                Some(*stream)
            } else {
                None
            }
        })
        .unwrap();
    let frame = messages
        .into_iter()
        .filter_map(|m| {
            if let ServerMessage::Frame { frame, .. } = m {
                Some(frame)
            } else {
                None
            }
        })
        .last()
        .unwrap();
    (peer, rx, stream, frame)
}
fn actor(host: &mut Host, id: u32) -> rusterix::Entity {
    let ctx = host.world.game().server.instances[0]
        .lock()
        .unwrap()
        .context()
        .unwrap();
    let actor = ctx
        .lock()
        .unwrap()
        .map
        .entities
        .iter()
        .find(|e| e.id == id)
        .unwrap()
        .clone();
    actor
}
fn assert_processed(messages: &[ServerMessage], sequence: u64) {
    assert!(messages.iter().any(|m| matches!(m, ServerMessage::ActionReply(reply) if reply.sequence == sequence && reply.result == ActionResult::Outcome(RequestOutcome::Processed))), "{messages:?}");
}

#[tokio::test]
async fn generated_bone_family_crosses_the_host_codec_with_private_ownership_and_replay_protection()
{
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../test_projects/3DStarter.eldiron");
    let mut project: Project =
        shared::project_io::decode_project(&std::fs::read(path).unwrap()).unwrap();
    project.migrate_default_ruleset();
    let mut document = project.rules_document.document().unwrap();
    let mut spec = BoneArmorFamily::default();
    spec.id = "test_bone".into();
    spec.classes =
        shared::rulesets::catalogue::Catalogue::from_table(document.table()).ids("classes");
    spec.preview(&document)
        .unwrap()
        .apply(&mut document)
        .unwrap();
    project.rules_document.current = document.to_toml().unwrap();
    project.preview_workbench_rules();
    let mut host = Host::open(project, None).await.unwrap();
    let (alice, mut a, stream, frame) = join(&mut host, "Armor crafter").await;
    let (bob, mut b, other_stream, other_frame) = join(&mut host, "Other player").await;
    drain(&mut a);
    let body = frame.controlled_entity.unwrap();
    // Explicit starting-stock fixture: the family guide itself grants nothing.
    {
        let ctx = host.world.game().server.instances[0]
            .lock()
            .unwrap()
            .context()
            .unwrap();
        let mut ctx = ctx.lock().unwrap();
        let mut stock = Vec::new();
        for (id, quantity) in [("bone_plate", 22), ("leather_strap", 13)] {
            let mut item = rusterix::Item::default();
            item.id = ctx.world.next_id();
            item.set_attribute("ruleset_id", rusterix::Value::Str(id.into()));
            item.set_attribute("quantity", rusterix::Value::Int(quantity));
            item.set_attribute("stackable", rusterix::Value::Bool(true));
            stock.push(item);
        }
        let player = ctx.map.entities.iter_mut().find(|e| e.id == body).unwrap();
        player.inventory.resize(32, None);
        for item in stock {
            player.add_item(item).unwrap();
        }
        player.set_attribute("armorsmithing", rusterix::Value::Int(100));
    }
    let mut members = Vec::new();
    for (index, (suffix, _, slot, _, _, _)) in BONE_PIECES.into_iter().enumerate() {
        // Keep this content-flow test within the host's real action budget.
        // Nine requests (including retries) precede this one-second window.
        if index == 3 {
            tokio::time::sleep(Duration::from_millis(1100)).await;
        }
        let sequence = index as u64 * 2 + 1;
        let craft = GameAction {
            stream,
            sequence,
            world: frame.world,
            generation: frame.generation,
            region: frame.current_region.unwrap(),
            request: GameRequest::Entity {
                target: body,
                intent: Some(format!("action:craft_test_bone_{suffix}")),
            },
        };
        message(&mut host, alice, ClientMessage::Action(craft.clone())).await;
        assert_processed(&drain(&mut a), sequence);
        let item = actor(&mut host, body)
            .inventory
            .into_iter()
            .flatten()
            .find(|i| i.attributes.get_str("ruleset_id") == Some(format!("test_bone_{suffix}").as_str()))
            .expect("crafted armor");
        message(&mut host, alice, ClientMessage::Action(craft)).await;
        assert_processed(&drain(&mut a), sequence);
        assert_eq!(
            actor(&mut host, body)
                .inventory
                .iter()
                .flatten()
                .filter(|i| i.attributes.get_str("ruleset_id")
                    == Some(format!("test_bone_{suffix}").as_str()))
                .count(),
            1
        );
        message(
            &mut host,
            alice,
            ClientMessage::Action(GameAction {
                stream,
                sequence: sequence + 1,
                world: frame.world,
                generation: frame.generation,
                region: frame.current_region.unwrap(),
                request: GameRequest::Transfer {
                    source: ItemSource::Direct(ItemAddress {
                        item: item.id,
                        owner: ItemOwner::Owned,
                    }),
                    destination: ItemDestination::Equipment(slot.into()),
                },
            }),
        )
        .await;
        assert_processed(&drain(&mut a), sequence + 1);
        let equipped = actor(&mut host, body);
        let equipped = equipped.get_equipped_item(slot).expect("equipped armor");
        assert_eq!(
            (equipped.id, equipped.creator_id),
            (item.id, item.creator_id)
        );
        members.push(item.id);
        drain(&mut b);
    }
    assert_eq!(
        members
            .iter()
            .collect::<std::collections::BTreeSet<_>>()
            .len(),
        5
    );
    message(
        &mut host,
        bob,
        ClientMessage::Action(GameAction {
            stream: other_stream,
            sequence: 1,
            world: other_frame.world,
            generation: other_frame.generation,
            region: other_frame.current_region.unwrap(),
            request: GameRequest::Transfer {
                source: ItemSource::Direct(ItemAddress {
                    item: members[0],
                    owner: ItemOwner::Owned,
                }),
                destination: ItemDestination::Inventory(None),
            },
        }),
    )
    .await;
    assert!(drain(&mut b).iter().any(|m| matches!(m, ServerMessage::ActionReply(reply) if reply.result == ActionResult::Outcome(RequestOutcome::Denied(RequestError::NotFound)))));
    assert_eq!(
        actor(&mut host, body).get_equipped_item("head").unwrap().id,
        members[0]
    );
}
